import{_ as e,o as l,c as a,a5 as i}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"视频批量处理工具","description":"","frontmatter":{"标题":"917-批量合并不同文件夹下的视频文件-穿透子文件夹","日期":"2026-04-19T00:00:00.000Z","修改日期":"2026-05-25T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["音频视频批处理"],"标签":["FFmpeg批量处理","Intel QSV编码","MP4合并","NVIDIA硬件加速","批量视频处理","硬件编码加速","视频尺寸调整","视频批量合并","视频格式转换","视频转码工具"]},"headers":[{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[]},{"level":2,"title":"环境要求","slug":"环境要求","link":"#环境要求","children":[{"level":3,"title":"最低要求","slug":"最低要求","link":"#最低要求","children":[]},{"level":3,"title":"推荐配置","slug":"推荐配置","link":"#推荐配置","children":[]},{"level":3,"title":"操作步骤","slug":"操作步骤","link":"#操作步骤","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"什么是硬件加速？","slug":"什么是硬件加速","link":"#什么是硬件加速","children":[]},{"level":3,"title":"各硬件加速方案对比","slug":"各硬件加速方案对比","link":"#各硬件加速方案对比","children":[]},{"level":3,"title":"目录结构变化","slug":"目录结构变化","link":"#目录结构变化","children":[]}]},{"level":2,"title":"故障排除","slug":"故障排除","link":"#故障排除","children":[{"level":3,"title":"问题 1：提示「无法找到 FFmpeg」","slug":"问题-1-提示「无法找到-ffmpeg」","link":"#问题-1-提示「无法找到-ffmpeg」","children":[]},{"level":3,"title":"问题 2：硬件编码器测试失败","slug":"问题-2-硬件编码器测试失败","link":"#问题-2-硬件编码器测试失败","children":[]},{"level":3,"title":"问题 3：内存不足","slug":"问题-3-内存不足","link":"#问题-3-内存不足","children":[]},{"level":3,"title":"问题 4：处理速度很慢","slug":"问题-4-处理速度很慢","link":"#问题-4-处理速度很慢","children":[]},{"level":3,"title":"问题 5：合并后视频有时间跳变","slug":"问题-5-合并后视频有时间跳变","link":"#问题-5-合并后视频有时间跳变","children":[]},{"level":3,"title":"问题 6：提示「编码不一致」但视频看起来正常","slug":"问题-6-提示「编码不一致」但视频看起来正常","link":"#问题-6-提示「编码不一致」但视频看起来正常","children":[]},{"level":3,"title":"问题 7：程序无响应或卡死","slug":"问题-7-程序无响应或卡死","link":"#问题-7-程序无响应或卡死","children":[]}]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[{"level":3,"title":"问题：程序提示找不到ffmpeg怎么办？","slug":"问题-程序提示找不到ffmpeg怎么办","link":"#问题-程序提示找不到ffmpeg怎么办","children":[]},{"level":3,"title":"Q: 支持哪些视频格式？","slug":"q-支持哪些视频格式","link":"#q-支持哪些视频格式","children":[]},{"level":3,"title":"Q: 可以处理 4K 视频吗？","slug":"q-可以处理-4k-视频吗","link":"#q-可以处理-4k-视频吗","children":[]},{"level":3,"title":"Q: 处理后的视频画质会下降吗？","slug":"q-处理后的视频画质会下降吗","link":"#q-处理后的视频画质会下降吗","children":[]},{"level":3,"title":"Q: 可以中断后继续处理吗？","slug":"q-可以中断后继续处理吗","link":"#q-可以中断后继续处理吗","children":[]},{"level":3,"title":"Q: 临时文件夹在哪里？","slug":"q-临时文件夹在哪里","link":"#q-临时文件夹在哪里","children":[]},{"level":3,"title":"Q: 如何只处理特定格式的视频？","slug":"q-如何只处理特定格式的视频","link":"#q-如何只处理特定格式的视频","children":[]},{"level":3,"title":"Q: 可以批量处理多个根文件夹吗？","slug":"q-可以批量处理多个根文件夹吗","link":"#q-可以批量处理多个根文件夹吗","children":[]}]}],"relativePath":"md/音频视频批处理/917-批量合并不同文件夹下的视频文件-穿透子文件夹.md","filePath":"md/音频视频批处理/917-批量合并不同文件夹下的视频文件-穿透子文件夹.md"}'),r={name:"md/音频视频批处理/917-批量合并不同文件夹下的视频文件-穿透子文件夹.md"};function n(o,t,d,s,h,p){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="视频批量处理工具" tabindex="-1">视频批量处理工具 <a class="header-anchor" href="#视频批量处理工具" aria-label="Permalink to &quot;视频批量处理工具&quot;">​</a></h1><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-7.png" alt=""></p><p>批量合并不同文件夹下的视频文件，支持自定义分辨率、统一编码格式。</p><p>这个工具可以一键把你散落在各个文件夹里的视频自动合并成MP4格式，还能统一调整成你想要的尺寸比例。支持MP4、AVI、MOV、WMV、FLV、MKV、WebM、M4V、ASF、TS、MTS这些常见格式，你只需要选一个根文件夹，点一下开始，程序就会自动扫描所有子文件夹，把每个文件夹里的视频分别合并成一个完整的MP4文件。不用你手动转换格式、不用你逐个调整比例，全部自动搞定，省时省力。</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><strong>多格式视频支持</strong>：支持MP4、AVI、MOV、WMV、FLV、MKV、WebM、M4V、ASF、TS、MTS共11种视频格式，无论你从哪里下载的视频都能处理。</p><p><strong>智能编码检测</strong>：程序会自动检测你电脑上的硬件编码器，优先使用NVIDIA、Intel、AMD的显卡加速，如果硬件不可用会自动切换到CPU编码，保证处理不中断。</p><p><strong>比例自动调整</strong>：可以选择把合并后的视频统一调整成1080x1080（1:1正方形）、1920x1080（16:9横屏）、1080x1920（9:16竖屏），或者保持原始尺寸不调整。</p><p><strong>批量文件夹处理</strong>：只需选择一个根文件夹，程序会自动遍历所有子文件夹，每个文件夹独立合并成一个视频，互不干扰。</p><p><strong>无损快速合并</strong>：当检测到所有视频的编码格式、分辨率、帧率完全一致时，程序会直接无损合并，速度极快，几秒钟就能完成。</p><p><strong>智能容错处理</strong>：编码失败时会自动尝试轻量模式，硬件加速不可用时自动降级到CPU，确保你的视频一定能处理完成。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>批量处理</td><td>自动扫描并处理所有子文件夹中的视频，支持递归遍历</td></tr><tr><td>编码检测</td><td>自动检测视频编码格式，识别不一致的视频</td></tr><tr><td>智能转码</td><td>仅对需要转码的视频进行处理，减少处理时间</td></tr><tr><td>分辨率调整</td><td>支持 1:1、16:9、9:16 或保持原尺寸</td></tr><tr><td>硬件加速</td><td>支持 NVIDIA NVENC、Intel QSV、AMD AMF 硬件编码</td></tr><tr><td>音频处理</td><td>统一音频格式为 AAC，自动处理音视频同步</td></tr><tr><td>内存优化</td><td>多级降级策略，针对低配置环境优化</td></tr><tr><td>临时清理</td><td>处理完成后自动清理临时文件</td></tr><tr><td>临时清理</td><td>处理完成后自动清理临时文件</td></tr></tbody></table><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><h3 id="最低要求" tabindex="-1">最低要求 <a class="header-anchor" href="#最低要求" aria-label="Permalink to &quot;最低要求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10/11 (64位)</td></tr><tr><td>内存</td><td>4GB RAM</td></tr><tr><td>内存</td><td>4GB RAM</td></tr></tbody></table><h3 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>推荐</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10/11 (64位)</td></tr><tr><td>内存</td><td>8GB RAM 或以上</td></tr><tr><td>处理器</td><td>多核处理器 (Intel i5 / AMD Ryzen 5 或更好)</td></tr><tr><td>处理器</td><td>多核处理器 (Intel i5 / AMD Ryzen 5 或更好)</td></tr></tbody></table><h1 id="使用前初始配置" tabindex="-1">使用前初始配置 <a class="header-anchor" href="#使用前初始配置" aria-label="Permalink to &quot;使用前初始配置&quot;">​</a></h1><p>将apitool文件夹复制到C盘根目录下，配置好的路径为：C:\\apitool</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li><strong>选择文件夹</strong>：点击「浏览」按钮，选择包含视频的根文件夹</li><li><strong>设置比例</strong>： <ul><li><code>1:1 (1080×1080)</code> - 方形视频，适用于 Instagram 等平台</li><li><code>16:9 (1920×1080)</code> - 宽屏视频，适用于 YouTube、电脑播放</li><li><code>9:16 (1080×1920)</code> - 竖屏视频，适用于抖音、快手等平台</li><li><code>不指定尺寸</code> - 保持原视频尺寸</li></ul></li><li><strong>选择加速方式</strong>： <ul><li><code>自动选择</code> - 程序自动检测可用的硬件加速（推荐）</li><li><code>英伟达显卡</code> - 强制使用 NVIDIA NVENC</li><li><code>Intel QSV</code> - 强制使用 Intel Quick Sync Video</li><li><code>AMD AMF</code> - 强制使用 AMD 硬件编码</li><li><code>使用CPU不加速</code> - 纯 CPU 编码，兼容性最好</li></ul></li><li><strong>开始处理</strong>：点击「开始处理」按钮</li><li><strong>查看进度</strong>：观察日志区域的处理进度</li><li><strong>完成处理</strong>：处理完成后，在原文件夹生成 <code>xxx_merged.mp4</code> 文件</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>确保视频文件格式支持（MP4, AVI, MOV, MKV, FLV, WMV ）</li><li>处理过程中请勿关闭程序或移动视频文件</li><li>建议处理前备份重要视频文件</li><li>大量视频处理可能需要较长时间，请耐心等待</li></ul><h3 id="什么是硬件加速" tabindex="-1">什么是硬件加速？ <a class="header-anchor" href="#什么是硬件加速" aria-label="Permalink to &quot;什么是硬件加速？&quot;">​</a></h3><p>硬件加速是利用显卡（GPU）的专用编码电路来加速视频编码，相比 CPU 编码可以提升 <strong>5-20 倍</strong> 的速度。</p><h3 id="各硬件加速方案对比" tabindex="-1">各硬件加速方案对比 <a class="header-anchor" href="#各硬件加速方案对比" aria-label="Permalink to &quot;各硬件加速方案对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>编码器</th><th>速度</th><th>画质</th><th>兼容性</th><th>推荐度</th></tr></thead><tbody><tr><td>NVIDIA</td><td>h264_nvenc</td><td>极快</td><td>中等</td><td>需要新驱动</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>Intel QSV</td><td>h264_qsv</td><td>快</td><td>中等</td><td>需要 Intel 显卡</td><td>⭐⭐⭐</td></tr><tr><td>AMD AMF</td><td>h264_amf</td><td>快</td><td>中等</td><td>需要 AMD 显卡</td><td>⭐⭐⭐</td></tr><tr><td>AMD AMF</td><td>h264_amf</td><td>快</td><td>中等</td><td>需要 AMD 显卡</td><td>⭐⭐⭐</td></tr></tbody></table><h3 id="目录结构变化" tabindex="-1">目录结构变化 <a class="header-anchor" href="#目录结构变化" aria-label="Permalink to &quot;目录结构变化&quot;">​</a></h3><p><strong>处理前</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根文件夹/└── 测试文件夹/    ├── 视频1.mp4    ├── 视频2.avi    └── 视频3.mkv</span></span></code></pre></div><p><strong>处理中（临时文件）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根文件夹/└── 测试文件夹/    ├── 视频1.mp4    ├── 视频2.avi    ├── 视频3.mkv    └── temp_videos/        └── processed_mp4/            ├── video_000.mp4            ├── video_001.mp4            ├── video_002.mp4            ├── black_pad.mp4            ├── concat.txt            └── merged_raw.mp4</span></span></code></pre></div><p><strong>处理后（最终结果）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根文件夹/└── 测试文件夹/    ├── 视频1.mp4    ├── 视频2.avi    ├── 视频3.mkv    └── 测试文件夹_merged.mp4  ← 最终输出文件</span></span></code></pre></div><hr><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><h3 id="问题-1-提示「无法找到-ffmpeg」" tabindex="-1">问题 1：提示「无法找到 FFmpeg」 <a class="header-anchor" href="#问题-1-提示「无法找到-ffmpeg」" aria-label="Permalink to &quot;问题 1：提示「无法找到 FFmpeg」&quot;">​</a></h3><p>请将apitool文件夹复制到C盘根目录下</p><h3 id="问题-2-硬件编码器测试失败" tabindex="-1">问题 2：硬件编码器测试失败 <a class="header-anchor" href="#问题-2-硬件编码器测试失败" aria-label="Permalink to &quot;问题 2：硬件编码器测试失败&quot;">​</a></h3><p><strong>症状</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[失败] 硬件编码器 h264_nvenc: The minimum required Nvidia driver for nvenc is 522.25 or newer</span></span></code></pre></div><p><strong>原因</strong>：显卡驱动版本过低</p><p><strong>解决方案</strong>：</p><ol><li>更新 NVIDIA 显卡驱动到最新版本</li><li>或在程序中选择「自动选择」让程序自动回退到 CPU</li><li>或选择「使用CPU不加速」</li></ol><p><strong>驱动下载</strong>：<a href="https://www.nvidia.cn/Download/index.aspx" target="_blank" rel="noreferrer">NVIDIA 官网驱动下载</a></p><h3 id="问题-3-内存不足" tabindex="-1">问题 3：内存不足 <a class="header-anchor" href="#问题-3-内存不足" aria-label="Permalink to &quot;问题 3：内存不足&quot;">​</a></h3><p><strong>症状</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OutOfMemoryError: [WinError 8] Not enough memory resources are available</span></span></code></pre></div><p><strong>原因</strong>：处理高分辨率视频时内存不足</p><p><strong>解决方案</strong>：</p><ol><li>关闭其他占用内存的程序</li><li>降低同时处理的视频数量</li><li>程序内置多级降级策略，会自动降低资源占用</li></ol><h3 id="问题-4-处理速度很慢" tabindex="-1">问题 4：处理速度很慢 <a class="header-anchor" href="#问题-4-处理速度很慢" aria-label="Permalink to &quot;问题 4：处理速度很慢&quot;">​</a></h3><p><strong>原因</strong>：使用了 CPU 编码而非硬件加速</p><p><strong>解决方案</strong>：</p><ol><li>确保已安装最新显卡驱动</li><li>选择「自动选择」或具体的显卡类型</li><li>检查是否误选了「使用CPU不加速」</li></ol><h3 id="问题-5-合并后视频有时间跳变" tabindex="-1">问题 5：合并后视频有时间跳变 <a class="header-anchor" href="#问题-5-合并后视频有时间跳变" aria-label="Permalink to &quot;问题 5：合并后视频有时间跳变&quot;">​</a></h3><p><strong>症状</strong>：视频播放到某个时间点突然跳到另一个时间</p><p><strong>原因</strong>：源视频的关键帧(GOP)间隔不一致</p><p><strong>解决方案</strong>：</p><ol><li>确保源视频的帧率一致</li><li>使用「不指定尺寸」模式</li><li>问题视频单独处理后再合并</li></ol><h3 id="问题-6-提示「编码不一致」但视频看起来正常" tabindex="-1">问题 6：提示「编码不一致」但视频看起来正常 <a class="header-anchor" href="#问题-6-提示「编码不一致」但视频看起来正常" aria-label="Permalink to &quot;问题 6：提示「编码不一致」但视频看起来正常&quot;">​</a></h3><p><strong>原因</strong>：某些视频虽然看起来正常，但编码参数（如 profile、level）有细微差异</p><p><strong>说明</strong>：这是正常的安全检查，程序会自动处理这些视频使其完全一致</p><h3 id="问题-7-程序无响应或卡死" tabindex="-1">问题 7：程序无响应或卡死 <a class="header-anchor" href="#问题-7-程序无响应或卡死" aria-label="Permalink to &quot;问题 7：程序无响应或卡死&quot;">​</a></h3><p><strong>原因</strong>：FFmpeg 处理大文件时可能耗时较长</p><p><strong>解决方案</strong>：</p><ol><li>等待处理完成（大文件可能需要几分钟或更久）</li><li>查看日志区域的进度信息</li><li>如需强制停止，点击「停止处理」按钮</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="问题-程序提示找不到ffmpeg怎么办" tabindex="-1">问题：程序提示找不到ffmpeg怎么办？ <a class="header-anchor" href="#问题-程序提示找不到ffmpeg怎么办" aria-label="Permalink to &quot;问题：程序提示找不到ffmpeg怎么办？&quot;">​</a></h3><p>答案：<strong>需要将apitool文件夹复制到C盘根目录下，效果：C:\\apitool</strong></p><h3 id="q-支持哪些视频格式" tabindex="-1">Q: 支持哪些视频格式？ <a class="header-anchor" href="#q-支持哪些视频格式" aria-label="Permalink to &quot;Q: 支持哪些视频格式？&quot;">​</a></h3><p>A: 支持 FFmpeg 支持的所有常见格式，包括：</p><ul><li>MP4, AVI, MOV, MKV, FLV, WMV</li><li>M4V, MPEG, MPG, 3GP, WebM</li><li>VOB, TS, M2TS</li></ul><h3 id="q-可以处理-4k-视频吗" tabindex="-1">Q: 可以处理 4K 视频吗？ <a class="header-anchor" href="#q-可以处理-4k-视频吗" aria-label="Permalink to &quot;Q: 可以处理 4K 视频吗？&quot;">​</a></h3><p>A: 可以，但建议：</p><ul><li>确保有 8GB 以上内存</li><li>使用硬件加速</li><li>有足够的硬盘空间存储临时文件</li></ul><h3 id="q-处理后的视频画质会下降吗" tabindex="-1">Q: 处理后的视频画质会下降吗？ <a class="header-anchor" href="#q-处理后的视频画质会下降吗" aria-label="Permalink to &quot;Q: 处理后的视频画质会下降吗？&quot;">​</a></h3><p>A: 使用默认参数(CRF 23)处理，画质几乎与原视频无肉眼可见差异。硬件加速的画质略低于 CPU 编码，但速度提升显著。</p><h3 id="q-可以中断后继续处理吗" tabindex="-1">Q: 可以中断后继续处理吗？ <a class="header-anchor" href="#q-可以中断后继续处理吗" aria-label="Permalink to &quot;Q: 可以中断后继续处理吗？&quot;">​</a></h3><p>A: 可以随时点击「停止处理」中断。临时文件不会被删除，下次处理时会自动跳过已完成的视频，如果没有中断，可通过关闭程序来实现。</p><h3 id="q-临时文件夹在哪里" tabindex="-1">Q: 临时文件夹在哪里？ <a class="header-anchor" href="#q-临时文件夹在哪里" aria-label="Permalink to &quot;Q: 临时文件夹在哪里？&quot;">​</a></h3><p>A: 在每个被处理的文件夹下，名为 <code>temp_videos</code>。处理完成后会自动删除。</p><h3 id="q-如何只处理特定格式的视频" tabindex="-1">Q: 如何只处理特定格式的视频？ <a class="header-anchor" href="#q-如何只处理特定格式的视频" aria-label="Permalink to &quot;Q: 如何只处理特定格式的视频？&quot;">​</a></h3><p>A: 当前版本会自动处理文件夹中的所有视频文件。</p><h3 id="q-可以批量处理多个根文件夹吗" tabindex="-1">Q: 可以批量处理多个根文件夹吗？ <a class="header-anchor" href="#q-可以批量处理多个根文件夹吗" aria-label="Permalink to &quot;Q: 可以批量处理多个根文件夹吗？&quot;">​</a></h3><p>A: 当前版本只支持处理单个根文件夹及其子文件夹。</p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，程序可以放在任意位置</strong>，演示视频中出现的弹窗部分已经修复。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-35.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2703.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2703.html</a></p>',99)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
